import { Helmet } from "react-helmet-async";
import { useTranslation } from "react-i18next";

interface SeoHeadProps {
  titleKey: string;
  descriptionKey: string;
  path?: string;
  /** 自定义 OG 图片路径（相对于站点根目录），不传则使用默认 og-image.png */
  image?: string;
}

const SITE_URL = (import.meta.env.VITE_SITE_URL || "https://qiekuo.github.io/hongyunx-site/").replace(/\/+$/, "");
const DEFAULT_OG_IMAGE = `${SITE_URL}/og-image.png`;

export function SeoHead({ titleKey, descriptionKey, path = "", image }: SeoHeadProps) {
  const { t } = useTranslation();
  const title = `${t(titleKey)} | HongyunX`;
  const description = t(descriptionKey);
  const url = path ? `${SITE_URL}/#/${path}` : `${SITE_URL}/`;
  const ogImage = image ? `${SITE_URL}/${image.replace(/^\/+/, "")}` : DEFAULT_OG_IMAGE;

  return (
    <Helmet>
      <title>{title}</title>
      <meta name="description" content={description} />
      <meta property="og:title" content={title} />
      <meta property="og:description" content={description} />
      <meta property="og:url" content={url} />
      <meta property="og:image" content={ogImage} />
      <meta property="og:image:width" content="1200" />
      <meta property="og:image:height" content="630" />
      <meta name="twitter:card" content="summary_large_image" />
      <meta name="twitter:title" content={title} />
      <meta name="twitter:description" content={description} />
      <meta name="twitter:image" content={ogImage} />
    </Helmet>
  );
}
